import {redirect} from "next/navigation";import {DashboardNav} from "@/components/DashboardNav";import {getOverview} from "@/lib/api";
export default async function Dashboard(){let data;try{data=await getOverview()}catch{redirect("/dashboard/login")}return <><DashboardNav dealer={data.dealer}/><main id="main" className="dashMain"><header className="dashHead"><div><span className="eyebrow">Overview</span><h1>Good to see you, {data.user.name}.</h1><p>{data.user.role} access</p></div></header><div className="statGrid">{Object.entries(data.counts).map(([k,v])=><article key={k}><span>{k}</span><strong>{v}</strong></article>)}</div><div className="dashColumns"><section className="panel"><h2>Recent inventory</h2>{data.vehicles.map(v=><div className="listRow" key={v.id}><span><strong>{v.title}</strong><small>{v.publication_status} · {v.availability}</small></span><span>v{v.version}</span></div>)}</section><section className="panel"><h2>Buyer requests</h2>{data.requests.map(r=><div className="listRow" key={r.id}><span><strong>{r.name}</strong><small>{r.kind} · {r.vehicle_title}</small></span><span className="status">{r.status}</span></div>)}</section></div><section className="panel"><h2>Marketplace delivery</h2>{data.outbox.map(e=><div className="listRow" key={e.id}><span><strong>{e.event_type}</strong><small>version {e.aggregate_version}</small></span><span className={`status ${e.status}`}>{e.status}</span></div>)}</section></main></>}
